/* THROWAWAY UI PROTOTYPE, Issue #1. No API, storage, database, AI, or personal data. */
const seed = [
  {id:'docker',name:'Docker',description:'Docker 将应用及其依赖打包在容器中。这里整理日常使用时最容易忘记的操作：进入终端、查看日志，以及容器排障。\n\n主题本身也是知识点，可以保存自己的描述并关联学习资料。',parents:[],materials:['file-docker','link-docker'],topic:true},
  {id:'exec',name:'进入容器终端',description:'容器已经在运行，想进入它的交互终端时，使用 docker exec。它会在已有容器里启动一个新进程，不会重新创建容器。\n\n先确认容器名称：\n```\ndocker ps\n```\n再进入终端：\n```\ndocker exec -it my-container /bin/bash\n```\n如果镜像没有 bash，改用 /bin/sh。退出终端输入 exit；容器的主进程会继续运行。\n\n我的理解：exec 是“进去执行”，不是“启动容器”。-i 保持标准输入，-t 分配伪终端。',parents:['docker'],materials:['file-docker','link-exec']},
  {id:'logs',name:'查看容器日志',description:'运行 docker logs -f my-container 可以持续查看容器标准输出和错误输出。排障时先看最后 100 行，再继续跟踪。\n```\ndocker logs --tail 100 -f my-container\n```',parents:['docker'],materials:['file-docker','link-docker']},
  {id:'troubleshoot',name:'容器排障',description:'先看状态，再看日志，最后进入容器验证。不要一上来就重建容器。\n\n1. docker ps -a：检查是否退出、是否反复重启。\n2. docker logs：查看报错。\n3. docker exec：进入终端，检查配置和网络。\n\n这份说明同时用于 Docker 和 Linux 运维，两个主题引用同一个知识点。',parents:['docker','linux'],materials:['file-docker','link-exec']},
  {id:'linux',name:'Linux 运维',description:'组织服务器、进程和容器的日常运维知识。容器排障同时属于 Docker 和这里，始终引用同一份描述与资料。',parents:[],materials:['file-docker'],topic:true},
  {id:'mysql',name:'MySQL',description:'整理关系数据库的事务、并发控制与锁。这里的锁关注数据库中对数据访问的协调。',parents:[],materials:['file-locks'],topic:true},
  {id:'mysql-lock',name:'锁',description:'MySQL 中，锁用于协调事务对数据的并发访问。排查锁等待时，要分清事务持有的锁与等待的锁。\n\n这里记录的是数据库的锁，与并发编程中的互斥锁是两个独立知识点。',parents:['mysql'],materials:['file-locks']},
  {id:'row-lock',name:'行锁',description:'行锁针对索引记录。理解事务访问了哪些记录，再分析锁等待。此点是 MySQL 的“锁”之下的知识点，用于演示主题删除的下属影响。',parents:['mysql-lock'],materials:['file-locks']},
  {id:'concurrency',name:'并发编程',description:'整理共享状态、线程协作与同步方法。这里的锁是进程或线程间的互斥机制。',parents:[],materials:['file-locks'],topic:true},
  {id:'code-lock',name:'锁',description:'并发编程中，互斥锁保护临界区，避免多个线程同时修改共享状态。\n\n使用时把临界区控制得尽量小，并明确加锁与释放路径。这里的“锁”与 MySQL 的“锁”分别保存，不会按名称自动合并。',parents:['concurrency'],materials:['file-locks']},
  {id:'independent',name:'待整理的想法',description:'尚未归入任何主题的独立知识点。删除其他主题时，这条记录仍然保留；不会因为没有所属主题而被全局清理。',parents:[],materials:[]}
];
const materials = {
  'file-docker':{name:'Docker 操作速查（演示文件）',kind:'file',type:'HTML',note:'本地只读演示 · 已就绪（模拟）',url:'assets/docker-demo.html'},
  'link-exec':{name:'Docker 官方文档：docker exec',kind:'link',type:'链接',note:'docs.docker.com · 公开外部链接',url:'https://docs.docker.com/reference/cli/docker/container/exec/'},
  'link-docker':{name:'Docker 官方文档',kind:'link',type:'链接',note:'docs.docker.com · 公开外部链接',url:'https://docs.docker.com/'},
  'file-locks':{name:'两种“锁”的学习摘记（演示文件）',kind:'file',type:'HTML',note:'本地只读演示 · 已就绪（模拟）',url:'assets/locks-demo.html'}
};
const variants={A:'图谱工作台',B:'检索工作台',C:'知识阅读台'};
let nodes=structuredClone(seed), graphNodes=structuredClone(seed);
let variant=new URLSearchParams(location.search).get('variant')||'A';
if(!variants[variant])variant='A';
let selected='exec',query='',matchMode='all',graphState='current',revision=1,graphRevision=1;
let toolsOpen=false,lastAction='已载入固定演示数据',saveMessage='',modalKind='',toastTimer;
let lastFocus=null;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=id=>nodes.find(n=>n.id===id);
const parentNames=n=>n.parents.map(id=>byId(id)?.name||id);
const selectedNode=()=>byId(selected);
const iconSearch='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>';
const brand='<div class="brand"><span class="brand-mark"><svg viewBox="0 0 30 32" fill="none" aria-hidden="true"><path d="M4 25V7l10 17V6m0 18L25 8v18" stroke="currentColor" stroke-width="1.9"/><circle cx="4" cy="7" r="2.4" fill="currentColor"/><circle cx="14" cy="24" r="2.4" fill="currentColor"/><circle cx="25" cy="8" r="2.4" fill="currentColor"/></svg></span>Noterion</div>';
function status(){return `<span class="status ${graphState==='current'?'':graphState==='offline'?'offline':'pending'}"><i></i>${graphState==='current'?'图谱已更新':graphState==='offline'?'图服务不可用':'图谱更新中'}</span>`;}
function results(){const words=query.trim().toLowerCase().split(/\s+/).filter(Boolean);return nodes.filter(n=>{const text=(n.name+' '+n.description).toLowerCase();return words.length===0||(matchMode==='all'?words.every(w=>text.includes(w)):words.some(w=>text.includes(w)));});}
function snippet(n){const plain=n.description.replace(/```/g,'').replace(/\n+/g,' ');const word=query.trim().split(/\s+/)[0]?.toLowerCase();const pos=word?plain.toLowerCase().indexOf(word):-1;const start=pos>40?pos-18:0;return (start?'…':'')+plain.slice(start,start+90)+(plain.length>start+90?'…':'');}
function searchBox(){return `<div class="searchbox">${iconSearch}<input data-search aria-label="搜索知识点名称或描述" placeholder="搜索名称或描述" value="${esc(query)}" autocomplete="off"><kbd>Ctrl K</kbd></div><div class="search-options"><span>多词</span><select data-match aria-label="多词匹配方式"><option value="all" ${matchMode==='all'?'selected':''}>全部匹配</option><option value="any" ${matchMode==='any'?'selected':''}>任意匹配</option></select><span>名称与描述</span></div>`;}
function quickQueries(){return `<div class="quick"><button data-query="docker exec">docker exec</button><button data-query="锁">锁</button><button data-query="容器排障">共享知识点</button></div>`;}
function resultList(table=false){const found=results();return `<div class="result-head"><span>${query?'搜索结果':'全部知识点'} <b>${found.length}</b></span><span>固定演示数据</span></div>${table?'<div class="result-table"><div class="table-header"><span>知识点与描述摘要</span><span>所属主题</span></div>':''}${found.length?found.map(n=>`<button class="result ${selected===n.id?'active':''}" data-select="${n.id}" aria-pressed="${selected===n.id}"><div><div class="result-title"><span>${esc(n.name)}</span>${!table?`<span class="tag">${n.topic?'主题':n.parents.length>1?'共享':''}</span>`:''}</div><div class="result-summary">${esc(snippet(n))}</div></div><div class="result-meta">${n.parents.length?parentNames(n).map(p=>`<span>${esc(p)}</span>`).join(''):`<span>${n.topic?'主题知识点':'独立知识点'}</span>`}</div></button>`).join(''):'<div class="empty">没有匹配的知识点。<br>试试名称的一部分，或描述中的命令。</div>'}${table?'</div>':''}`;}
function formattedDescription(n){return n.description.split('```').map((s,i)=>i%2?`<code>${esc(s.trim())}</code>`:esc(s.trim())).join('');}
function detailHead(n){return `<div class="detail-head"><div class="eyeline">${n.topic?'主题知识点':n.parents.length>1?'共享知识点':'知识点'}</div><h1>${esc(n.name)}</h1><div class="button-row">${n.parents.length?n.parents.map(id=>`<button class="pill topic-pill" data-select="${id}">${esc(byId(id)?.name)}</button>`).join(''):`<span class="pill">${n.topic?'主题也是知识点':'独立知识点'}</span>`}</div><div class="button-row"><button class="btn" data-edit="${n.id}">编辑知识点</button><button class="btn" data-focus-graph>在图中定位</button></div>${saveMessage?`<div class="save-state">${esc(saveMessage)}</div>`:''}</div>`;}
function resourceList(n){return `<section class="detail-section"><div class="section-label"><h3>学习资料</h3><small>${n.materials.length} 份</small></div>${n.materials.length?n.materials.map(id=>{const m=materials[id];return `<div class="resource"><div class="resource-icon">${m.type}</div><div class="resource-info"><strong>${esc(m.name)}</strong><small>${esc(m.note)}</small></div>${m.kind==='link'?`<a class="btn" data-external="${id}" href="${m.url}" target="_blank" rel="noopener noreferrer">打开 ↗</a>`:`<button class="icon-btn" data-material="${id}">查看</button>`}</div>`;}).join(''):'<p class="muted" style="font-size:13px">这个知识点暂未关联资料。</p>'}</section>`;}
function childList(n){const children=nodes.filter(x=>x.parents.includes(n.id));return children.length?`<section class="detail-section"><h3 style="margin-bottom:10px">下属知识点</h3><div class="children">${children.map(x=>`<button data-select="${x.id}">${esc(x.name)}${x.parents.length>1?' ↗':''}</button>`).join('')}</div></section>`:'';}
function identity(n){return `<details class="identity"><summary>查看知识点身份</summary><pre>演示 ID：${n.id}\n所属主题：${esc(parentNames(n).join('、')||'无')}\n资料 ID：${esc(n.materials.join(', ')||'无')}\n名称相同不会合并身份</pre></details>`;}
function detail(){const n=selectedNode();if(!n)return '<div class="empty">选择一个知识点，阅读描述与资料。</div>';return `${detailHead(n)}<section class="detail-section"><h3>完整描述</h3><div class="description">${formattedDescription(n)}</div></section>${resourceList(n)}${childList(n)}${identity(n)}`;}
const topicColors={docker:'#5687cb',linux:'#4c9e91',mysql:'#c59450',concurrency:'#9279b8'};
let graphFocusRequested=false;
const uiPaths={network:'M5 5h4v4H5zM15 15h4v4h-4zM4 16h4v4H4zM17 4h3v3h-3zM9 9l6 6M9 7h8M7 9v7',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14m5-2 6 6',book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4zm16 0h-4a3 3 0 0 0-3 3m7-3v14h-3a4 4 0 0 0-4 3',focus:'M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M9 9h6v6H9z',fit:'M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M7 7l3 3m7-3-3 3M7 17l3-3m7 3-3-3',edit:'m5 16-1 4 4-1L20 7l-3-3L5 16zm9-9 3 3',trash:'M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 10v7m4-7v7',labels:'M4 5h16M12 5v15M8 20h8',link:'M10 14l4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',chevron:'m9 5 7 7-7 7'};
function uiIcon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${uiPaths[name]||uiPaths.network}"/></svg>`;}
function hue(n,seen=new Set()){if(!n||seen.has(n.id))return '#8a98ab';if(topicColors[n.id])return topicColors[n.id];seen.add(n.id);return hue(graphNodes.find(x=>x.id===n.parents[0]),seen);}
function radius(n){return n.topic?26:n.id===selected?15:n.parents.length>1?14:10;}
function nodeSymbol(n){if(n.topic){const path=n.id==='docker'?'M-11-7h7v6h-7zm9 0h7v6h-7zm9 0h7v6H7zM-7-15h7v6h-7zm9 0h7v6H2zM-14 2h28c-2 8-8 12-15 10-7-1-11-4-13-10':n.id==='mysql'?'M-11-9c0-6 22-6 22 0s-22 6-22 0m0 0V8c0 6 22 6 22 0V-9M-11-1c0 6 22 6 22 0':n.id==='linux'?'m-10-6 7 6-7 6M1 7h9':'m-6-10-8 10 8 10m12-20 8 10-8 10';return `<path class="node-symbol" d="${path}" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/>`;}
 if(n.id===selected)return '<circle r="3" class="node-core"/>';
 return '';
}
function positions(local){
 if(local){const n=graphNodes.find(x=>x.id===selected);if(!n)return {list:[],pos:{}};const parents=graphNodes.filter(x=>n.parents.includes(x.id));const children=variant==='C'?[]:graphNodes.filter(x=>x.parents.includes(n.id));const list=[...parents,n,...children],pos={[n.id]:[0,variant==='C'?85:0]};parents.forEach((x,i)=>pos[x.id]=variant==='C'?[(i-(parents.length-1)/2)*135,-65]:[-180,(i-(parents.length-1)/2)*85]);children.forEach((x,i)=>pos[x.id]=[180,(i-(children.length-1)/2)*65]);return {list,pos};}
 const pos={docker:[245,205],exec:[150,110],logs:[115,305],troubleshoot:[420,225],linux:[595,155],mysql:[280,450],'mysql-lock':[170,520],'row-lock':[110,625],concurrency:[665,430],'code-lock':[745,565],independent:[505,645]};return {list:graphNodes,pos};
}
function graph(local=false){
 const {list,pos}=positions(local),n=selectedNode(),modalGraph=modalKind==='global',key=`${variant}-${local?'local':'all'}-${modalGraph?'modal':'main'}`,marker=`arrow-${key}`;
 let content='';
 if(graphState!=='current'){
  content=`<div class="graph-unavailable"><div><span class="offline-symbol">${uiIcon(graphState==='offline'?'network':'focus')}</span><h3>${graphState==='offline'?'图谱暂时不可用':'图谱更新中'}</h3><p>${graphState==='offline'?'搜索、描述和学习资料仍可使用。连接恢复并赶上更新后，继续浏览图谱。':`内容已保存（模拟）。图版本 ${graphRevision} 正在赶上内容版本 ${revision}。`}</p><button class="btn" data-catchup>${graphState==='offline'?'模拟恢复连接':'模拟图已赶上'}</button></div></div>`;
 }else{
  const shown=new Set(list.map(x=>x.id));
  const edges=list.flatMap(x=>x.parents.filter(p=>shown.has(p)).map((p,i)=>`<path class="edge ${x.id===selected||p===selected?'connected':''}" data-from="${x.id}" data-to="${p}" data-from-radius="${radius(x)}" data-to-radius="${radius(graphNodes.find(z=>z.id===p))}" data-bend="${x.parents.length>1?(i?15:-15):8}" marker-end="url(#${marker})"/>`)).join('');
  const shapes=list.map(x=>{const [px,py]=pos[x.id],r=radius(x),active=x.id===selected,isLock=x.name==='锁';return `<g class="node ${x.topic?'topic':''} ${x.parents.length>1?'shared':''} ${active?'selected':''}" style="--node-color:${hue(x)}" data-x="${px}" data-y="${py}" data-select="${x.id}" tabindex="0" role="button" aria-label="图中知识点 ${esc(x.name)}${isLock?'，'+esc(x.parents.map(p=>graphNodes.find(z=>z.id===p)?.name).join('、')):''}" aria-pressed="${active}"><title>${esc(x.name)} · ${x.id}</title>${active?`<circle class="selection-wash" r="${r+15}"/><circle class="selection-ring" r="${r+7}"/>`:''}<circle class="node-hit" r="${r+12}"/><circle class="node-shape" r="${r}"/>${nodeSymbol(x)}${x.parents.length>1?`<path class="shared-ring" d="M ${-r-4} 0 A ${r+4} ${r+4} 0 0 1 ${r+4} 0"/>`:''}<text class="node-label" text-anchor="middle" y="${r+24}">${esc(x.name)}</text>${isLock?`<text class="node-context" text-anchor="middle" y="${r+43}">${esc(x.parents.map(p=>graphNodes.find(z=>z.id===p)?.name).join('、'))}</text>`:''}</g>`;}).join('');
  content=`<svg class="graph-svg ${local?'local-svg':''}" data-view-key="${key}" data-focus="${graphFocusRequested}" aria-label="${local?'当前知识点的局部所属主题图':'演示知识图谱'}" role="group"><defs><marker id="${marker}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto"><path d="M 1 1 L 9 5 L 1 9" fill="none" stroke="#9ba8b7" stroke-width="1.4"/></marker></defs><g class="edges">${edges}</g><g class="nodes">${shapes}</g></svg>`;
 }
 const legend=!local?`<div class="graph-legend">${Object.entries(topicColors).filter(([id])=>list.some(x=>x.id===id)).map(([id,color])=>`<span><i style="background:${color}"></i>${esc(graphNodes.find(x=>x.id===id)?.name)}</span>`).join('')}<span class="relation-key">→ 所属主题</span></div>`:'';
 const controls=graphState==='current'?`<div class="canvas-tools"><button data-graph-action="out" aria-label="缩小图谱" title="缩小">−</button><span data-zoom-level>100%</span><button data-graph-action="in" aria-label="放大图谱" title="放大">+</button><i></i><button data-graph-action="fit" aria-label="适应全部节点" title="适应全部节点">${uiIcon('fit')}</button></div>`:'';
 return `<div class="graph-shell ${local?'local-graph':''}"><div class="graph-toolbar"><div class="graph-title"><h2>${local?'所属主题':'知识图谱'}</h2>${status()}</div><div class="graph-actions">${graphState==='current'?`<button class="icon-btn graph-label-toggle" data-graph-action="labels" aria-label="显示节点名称" aria-pressed="true" title="显示或隐藏名称">${uiIcon('labels')}</button>${!local?`<button class="icon-btn" data-graph-action="neighbors" aria-label="仅看当前节点关联" aria-pressed="false" title="仅看当前节点关联">${uiIcon('network')}</button>`:''}`:''}${!modalGraph?`<button class="btn graph-expand" data-global>${uiIcon('focus')} 全图</button>`:''}</div></div><div class="graph-space">${content}${legend}${controls}</div><div class="graph-location"><span><i class="location-dot" style="background:${n?hue(n):'#8a98ab'}"></i>${graphState==='current'?esc(n?.name||'未选择'):'图中定位暂不可用'}</span><div class="graph-object-actions"><button class="icon-btn" data-edit="${esc(selected)}" aria-label="编辑图中知识点" title="编辑知识点">${uiIcon('edit')}</button><button class="icon-btn danger" data-delete="${esc(selected)}" aria-label="在图中删除${n?.topic?'主题':'知识点'}" title="在图中删除${n?.topic?'主题':'知识点'}" ${graphState!=='current'||!n?'disabled':''}>${uiIcon('trash')}</button></div></div></div>`;
}
function VariantA(){return `<main class="a"><header class="app-header">${brand}<nav><button class="header-active" data-focus-graph>知识图谱</button><button data-library>学习资料</button></nav><span class="demo-tag">演示数据</span></header><aside class="rail"><button class="rail-active" title="知识图谱" data-focus-graph aria-label="知识图谱">${uiIcon('network')}</button><button title="搜索知识点" data-open-search aria-label="搜索知识点">${uiIcon('search')}</button><button title="演示资料库" data-library aria-label="演示资料库">${uiIcon('book')}</button></aside><section class="search-panel"><h2 class="panel-title">查找知识点</h2>${searchBox()}${quickQueries()}<div data-results>${resultList()}</div></section><section class="graph-panel">${graph()}</section><aside class="detail-panel">${detail()}</aside></main>`;}
function VariantB(){return `<main class="b"><header class="b-header">${brand}<nav><span class="active-tab">查找知识</span><button data-global>浏览图谱</button><button data-library>演示资料库</button></nav>${status()}</header><div class="b-workspace"><section class="retrieval"><div class="query-title"><h1>查找知识点</h1><span class="eyeline">名称、命令或描述片段</span></div>${searchBox()}${quickQueries()}<div data-results>${resultList(true)}</div><section class="context-map">${graph(true)}</section></section><article class="reading-pane">${detail()}</article></div></main>`;}
function VariantC(){const n=selectedNode();return `<main class="c"><header class="c-header">${brand}<button class="search-trigger" data-open-search>${iconSearch} 查找知识点 <kbd>Ctrl K</kbd></button><div class="button-row">${status()}<button class="btn" data-library>演示资料库</button></div></header><nav class="topic-ribbon"><span class="eyeline">所属主题</span>${nodes.filter(x=>x.topic).map(x=>`<button class="topic-tab ${n?.parents.includes(x.id)||n?.id===x.id?'active':''}" data-select="${x.id}">${esc(x.name)}</button>`).join('')}<button class="topic-tab" data-open-search>全部知识点</button></nav><div class="c-scroll"><article class="document"><div class="document-main">${n?`${detailHead(n)}<section class="detail-section"><h3>完整描述</h3><div class="description">${formattedDescription(n)}</div></section>${resourceList(n)}`:'<div class="empty">选择一个知识点开始阅读。</div>'}</div><aside class="document-margin"><section class="context-map">${graph(true)}</section><div class="margin-content">${n?`${childList(n)}${identity(n)}`:''}<section class="detail-section"><h3>继续查找</h3><div class="children"><button data-query="docker exec">忘记容器命令</button><button data-query="锁">区分两种“锁”</button><button data-query="容器排障">查看共享知识点</button></div></section></div></aside></article></div></main>`;}
function stateSnapshot(){return {variant,selected,query,matchMode,graphState,simulatedSourceRevision:revision,graphRevision,knowledgePointCount:nodes.length,knowledgePoints:nodes.map(n=>({id:n.id,name:n.name,parents:n.parents,materials:n.materials})),fileCount:Object.values(materials).filter(m=>m.kind==='file').length,lastAction,graphViews:PrototypeGraph.snapshot(),persistence:'none; reload resets demo'};}
function prototypeTools(){document.querySelector('#prototype-tools').innerHTML=`<div class="switcher" role="navigation" aria-label="原型方案切换"><button class="arrow" data-cycle="-1" aria-label="上一个方案">‹</button>${Object.entries(variants).map(([key,name])=>`<button class="${variant===key?'current':''}" data-variant="${key}" aria-current="${variant===key?'page':'false'}">${key} ${name}</button>`).join('')}<button class="arrow" data-cycle="1" aria-label="下一个方案">›</button></div><div class="prototype-banner"><span>交互原型 · 演示数据仅在当前页面生效</span><span>当前：${esc(selectedNode()?.name||'未选择')} <span class="desktop-note"> / ${graphState==='current'?'图已更新':graphState==='offline'?'图不可用':'图更新中'}</span>　<button data-tools>${toolsOpen?'收起':'演示控制与状态'}</button></span></div>${toolsOpen?`<aside class="tool-drawer"><div class="section-label"><h2>演示控制与状态</h2><button data-tools aria-label="关闭演示控制">✕</button></div><p>所有修改仅存在于当前页面内存。刷新或重置会重新载入固定数据。这些状态没有验证真实保存、图同步或对象存储。</p><label for="graph-state">模拟图服务状态</label><select id="graph-state" data-graph-state><option value="current" ${graphState==='current'?'selected':''}>图谱已更新</option><option value="pending" ${graphState==='pending'?'selected':''}>图谱更新中</option><option value="offline" ${graphState==='offline'?'selected':''}>图服务不可用</option></select><p style="margin-top:12px">结构数据版本 ${revision} / 图版本 ${graphRevision}；知识点 ${nodes.length} 个；文件资料 2 份。</p><div class="button-row"><button class="btn" data-reset>重置全部演示数据</button><button class="btn" data-library>查看保留的资料</button></div><details><summary>查看完整演示状态</summary><pre>${esc(JSON.stringify(stateSnapshot(),null,2))}</pre></details><details><summary>交给 #2 的选择问题</summary><p>哪套主次关系最顺手？是否组合某套的搜索与另一套的描述区？共享点和同名结果能否辨认？删除影响和图更新状态是否容易理解？<br>目前没有选定方案。</p></details></aside>`:''}`;}
function render(){PrototypeGraph.dispose();document.body.dataset.variant=variant;document.body.classList.toggle('is-searching',Boolean(query.trim()));app.innerHTML=({A:VariantA,B:VariantB,C:VariantC}[variant])();PrototypeGraph.mountAll();graphFocusRequested=false;prototypeTools();}
function notify(message){const box=document.querySelector('#toast');box.textContent=message;box.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.style.display='none',3500);}
function switchVariant(key){variant=key;const url=new URL(location.href);url.searchParams.set('variant',key);history.replaceState({},'',url);lastAction=`切换到方案 ${key}：${variants[key]}`;render();}
function selectNode(id,focus=true){if(!byId(id))return;if(selected!==id)saveMessage='';selected=id;graphFocusRequested=focus;lastAction=`选择知识点 ${id}${graphState==='current'?' 并在图中定位':'；图定位暂不可用'}`;if(modalKind==='search')closeModal();render();}
function setQuery(value){query=value;lastAction=`搜索 ${value||'全部知识点'}`;if(variant==='C'&&modalKind!=='search')openSearch();else updateResults();}
function updateResults(){document.body.classList.toggle('is-searching',Boolean(query.trim()));const target=document.querySelector('[data-results]');if(target)target.innerHTML=resultList(variant==='B'&&modalKind!=='search');document.querySelectorAll('[data-search]').forEach(x=>{if(x!==document.activeElement)x.value=query;});prototypeTools();}
function showModal(kind,html){lastFocus=document.activeElement;modalKind=kind;modal.className=kind==='global'?'global-graph-dialog':'';modal.innerHTML=html;modal.showModal();PrototypeGraph.mountAll();}
function closeModal(){modal.close();modalKind='';modal.innerHTML='';lastFocus?.focus?.();}
function openSearch(){if(modal.open)closeModal();showModal('search',`<div class="search-dialog"><div class="modal-head"><div><h2>查找知识点</h2><p>搜索名称与完整描述，点击结果回到图谱和阅读区。</p></div><button data-close aria-label="关闭搜索">✕</button></div><div class="modal-body">${searchBox()}${quickQueries()}<div data-results>${resultList()}</div></div></div>`);modal.querySelector('input')?.focus();}
function openEdit(id){const n=byId(id);showModal('edit',`<form id="edit-form" data-id="${id}"><div class="modal-head"><div><h2>编辑 ${esc(n.name)}</h2><p>${n.parents.length>1?'此知识点被多个主题引用，修改会在所有入口显示。':'修改名称、描述或所属主题。'} 演示 ID：${id}</p></div><button type="button" data-close aria-label="关闭编辑">✕</button></div><div class="modal-body"><label class="field">名称<input name="name" required value="${esc(n.name)}" maxlength="60"></label><label class="field">完整描述<textarea name="description">${esc(n.description)}</textarea></label><div class="field">所属主题（固定演示主题）<div class="checks">${nodes.filter(x=>x.topic&&x.id!==id).map(x=>`<label><input type="checkbox" name="parents" value="${x.id}" ${n.parents.includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')}</div></div><p class="modal-note">移除所属主题只断开关系，知识点可保持独立。这里模拟保存到正式结构数据，图谱另行更新。</p></div><div class="modal-foot"><button class="btn" type="button" data-close>取消</button><button class="btn primary" type="submit">保存修改（模拟）</button></div></form>`);}
function saveEdit(form){const n=byId(form.dataset.id),data=new FormData(form);n.name=String(data.get('name')).trim();if(!n.name){notify('请输入知识点名称');return;}n.description=String(data.get('description'));const chosen=data.getAll('parents').map(String);n.parents=[...n.parents.filter(p=>!nodes.some(x=>x.topic&&x.id===p)),...chosen];revision++;if(graphState!=='offline')graphState='pending';saveMessage='已保存（模拟）；图谱状态独立更新';lastAction=`已模拟保存 ${n.id}，数据版本 ${revision}`;closeModal();render();notify('已保存（仅内存模拟），图谱尚未赶上');}
function deletionImpact(id){const removed=new Set([id]);let changed=true;while(changed){changed=false;nodes.forEach(n=>{if(!removed.has(n.id)&&n.parents.some(p=>removed.has(p))&&n.parents.every(p=>removed.has(p))){removed.add(n.id);changed=true;}});}const shared=nodes.filter(n=>!removed.has(n.id)&&n.parents.some(p=>removed.has(p)));return {removed:nodes.filter(n=>removed.has(n.id)),shared};}
function openDelete(id){if(graphState!=='current'||!byId(id))return;const n=byId(id),impact=deletionImpact(id);showModal('delete',`<div class="modal-head"><div><h2>从图中删除“${esc(n.name)}”</h2><p>当前图中选中的知识点：${id}。以下是本次模拟删除的影响。</p></div><button data-close aria-label="关闭删除确认">✕</button></div><div class="modal-body"><section class="impact"><h3>将移除 ${impact.removed.length} 个知识点及其描述</h3>${impact.removed.map(x=>`<span class="pill">${esc(x.name)} <small>${x.id}</small></span>`).join('')}</section><section class="impact"><h3>共享知识点保留</h3><p>${impact.shared.length?impact.shared.map(x=>`${esc(x.name)} → 仍属于 ${esc(x.parents.filter(p=>!impact.removed.some(r=>r.id===p)).map(p=>byId(p)?.name).join('、'))}`).join('<br>'):'本次没有受影响的共享知识点。'}</p></section><section class="impact"><h3>文件资料与原有独立知识点保留</h3><p>两份演示文件仍可从“演示资料库”打开。本次范围外的原有独立知识点不变。</p></section><p class="modal-note">直接移除，没有回收站或删除后恢复。此操作仅改变当前页面的演示数据；“重置演示”是原型工具。</p></div><div class="modal-foot"><button class="btn" data-close>取消</button><button class="btn primary danger" data-confirm-delete="${id}">确认模拟删除</button></div>`);}
function confirmDelete(id){const impact=deletionImpact(id),ids=new Set(impact.removed.map(n=>n.id));nodes=nodes.filter(n=>!ids.has(n.id)).map(n=>({...n,parents:n.parents.filter(p=>!ids.has(p))}));if(ids.has(selected))selected=impact.shared[0]?.id||nodes[0]?.id||'';revision++;graphState='pending';saveMessage='';lastAction=`模拟删除 ${[...ids].join(', ')}，共享保留 ${impact.shared.map(x=>x.id).join(', ')||'无'}`;closeModal();render();notify('知识点已模拟移除，文件资料保留；图谱待更新');}
function openMaterial(id){const m=materials[id];lastAction=`打开演示文件 ${id}`;showModal('file',`<div class="modal-head"><div><h2>${esc(m.name)}</h2><p>只读演示文件 · 未连接对象存储 · 文件在本原型目录中</p></div><button data-close aria-label="关闭文件预览">✕</button></div><div class="modal-body"><iframe class="file-preview" src="${m.url}" title="${esc(m.name)}" sandbox></iframe><div class="preview-link"><a href="${m.url}" target="_blank" rel="noopener">在新窗口打开文件 ↗</a><a href="${m.url}" download>下载演示文件</a></div></div><div class="modal-foot"><button class="btn" data-close>关闭</button></div>`);prototypeTools();}
function openLibrary(){showModal('library',`<div class="modal-head"><div><h2>演示资料库</h2><p>资料独立保留。删除知识点不会删除以下演示文件。</p></div><button data-close aria-label="关闭资料库">✕</button></div><div class="modal-body">${Object.entries(materials).map(([id,m])=>`<div class="resource"><div class="resource-icon">${m.type}</div><div class="resource-info"><strong>${esc(m.name)}</strong><small>${m.kind==='file'?'文件始终保留 · 本地演示文件':'公开外部链接'}</small></div>${m.kind==='file'?`<button class="btn" data-library-material="${id}">查看</button>`:`<a class="btn" href="${m.url}" target="_blank" rel="noopener">打开 ↗</a>`}</div>`).join('')}</div><div class="modal-foot"><button class="btn" data-close>关闭</button></div>`);}
function catchUp(){if(graphState==='offline'){graphState='pending';lastAction='模拟连接恢复；尚未赶上数据，图定位继续暂停';render();notify('图连接已恢复（模拟），仍需等待赶上更新');}else{graphNodes=structuredClone(nodes);graphRevision=revision;graphState='current';lastAction=`图已模拟赶上版本 ${revision}`;render();notify('图谱已更新（模拟），可以继续浏览和定位');}}
function openGlobal(){modalKind='global';showModal('global',`<div class="modal-head"><div><h2>全部知识图谱</h2><p>知识点间只展示所属主题。学习资料从详情打开。</p></div><button data-close aria-label="关闭全图">✕</button></div><div class="global-graph-wrap">${graph()}</div>`);}
document.addEventListener('input',e=>{if(e.target.matches('[data-search]')){query=e.target.value;updateResults();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-match]')){matchMode=e.target.value;updateResults();}if(e.target.matches('[data-graph-state]')){const value=e.target.value;if(value==='current'){if(graphState==='offline')graphState='pending';else{graphNodes=structuredClone(nodes);graphRevision=revision;graphState='current';}}else graphState=value;lastAction=`设置模拟图状态：${graphState}`;render();}});
document.addEventListener('submit',e=>{if(e.target.id==='edit-form'){e.preventDefault();saveEdit(e.target);}});
document.addEventListener('click',e=>{const graphNode=e.target.closest('.node');if(graphNode){if(modalKind==='global')closeModal();selectNode(graphNode.dataset.select,false);return;}const t=e.target.closest('button,a');if(!t)return;
 if(t.dataset.select){if(modalKind==='global'){closeModal();}selectNode(t.dataset.select);return;}
 if(t.dataset.variant){switchVariant(t.dataset.variant);return;}
 if(t.dataset.cycle){const keys=Object.keys(variants);switchVariant(keys[(keys.indexOf(variant)+Number(t.dataset.cycle)+3)%3]);return;}
 if(t.hasAttribute('data-query')){setQuery(t.dataset.query);return;}
 if(t.hasAttribute('data-open-search')){if(variant==='C')openSearch();else{const input=app.querySelector('[data-search]');input?.focus();input?.select();}return;}
 if(t.hasAttribute('data-tools')){toolsOpen=!toolsOpen;prototypeTools();return;}
 if(t.hasAttribute('data-close')){closeModal();return;}
 if(t.dataset.edit){openEdit(t.dataset.edit);return;}
 if(t.dataset.delete){if(modalKind==='global')closeModal();openDelete(t.dataset.delete);return;}
 if(t.dataset.confirmDelete){confirmDelete(t.dataset.confirmDelete);return;}
 if(t.dataset.material){openMaterial(t.dataset.material);return;}
 if(t.dataset.libraryMaterial){closeModal();openMaterial(t.dataset.libraryMaterial);return;}
 if(t.dataset.external){lastAction=`打开外部资料 ${t.dataset.external}`;prototypeTools();return;}
 if(t.hasAttribute('data-library')){openLibrary();return;}
 if(t.hasAttribute('data-catchup')){if(modalKind==='global')closeModal();catchUp();return;}
 if(t.hasAttribute('data-global')){openGlobal();return;}
 if(t.hasAttribute('data-focus-graph')){if(graphState!=='current'){notify('图谱尚不可用，描述和资料可继续使用');return;}PrototypeGraph.focus();app.querySelector('.graph-space')?.scrollIntoView({block:'nearest',behavior:'smooth'});app.querySelector(`.node[data-select="${selected}"]`)?.focus();notify(`已在图中定位：${selectedNode()?.name}`);return;}
 if(t.hasAttribute('data-reset')){PrototypeGraph.reset();nodes=structuredClone(seed);graphNodes=structuredClone(seed);selected='exec';query='';matchMode='all';graphState='current';revision=graphRevision=1;saveMessage='';lastAction='重新载入固定演示数据（非业务恢复）';render();notify('已重新载入固定演示数据');}
});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(variant==='C')openSearch();else app.querySelector('[data-search]')?.focus();return;}
 if(e.target.matches('.node')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();if(modalKind==='global')closeModal();selectNode(e.target.dataset.select);return;}
 if(modal.open||e.target.closest('input,textarea,select,[contenteditable]'))return;
 if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const keys=Object.keys(variants);switchVariant(keys[(keys.indexOf(variant)+(e.key==='ArrowRight'?1:2))%3]);}
});
modal.addEventListener('cancel',e=>{e.preventDefault();closeModal();});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
render();
